# ==========================================
# 🔒 감독관 로그인: 2초 모션 스플래시 + 현장사진 로그인 (UI 24)
# ==========================================
def check_password():
    if st.session_state.get("password_correct", False):
        return True

    # 로그인 전용: PC 소개 카드 / 모바일 압축 레이아웃
    st.markdown("""
    <style>
    @media (min-width: 769px) {
        .login-page-heading.login-heading-v24 {
            container-type: inline-size;
            box-sizing: border-box;
            width: 100%;
            text-align: left;
            padding: 24px clamp(16px, 2vw, 28px);
            margin: 4px 0 20px;
            border: 1px solid #dce9e4 !important;
            border-left: 4px solid #069668 !important;
            border-radius: 18px !important;
            background: linear-gradient(115deg, #ffffff 0%, #f0f8f4 100%) !important;
            box-shadow: 0 6px 22px rgba(18, 65, 49, 0.045);
        }
        .login-page-title {
            font-size: clamp(14px, 1.7vw, 30px) !important;
            font-size: clamp(12px, 4.1cqi, 30px) !important;
            font-weight: 800 !important;
            line-height: 1.5 !important;
            letter-spacing: -0.055em !important;
            white-space: nowrap;
            padding: 0 !important;
            color: #183d34 !important;
        }
        .login-page-title br { display: none; }
        .login-page-title span::before { content: " "; }
        .login-page-title span { color: #00855b !important; }
        .login-page-subtitle {
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 12px 0 0 !important;
            font-size: clamp(11px, 2.25cqi, 14px) !important;
            font-weight: 400;
            color: #586f67 !important;
            letter-spacing: -0.02em;
        }
        .login-page-subtitle::before {
            content: "";
            flex: 0 0 6px;
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: #059669;
        }
    }
    @media (max-width: 768px) {
        .block-container {
            padding-top: 1rem !important;
            padding-bottom: 0.75rem !important;
            padding-left: 1rem !important;
            padding-right: 1rem !important;
        }
        [data-testid="stVerticalBlock"] { gap: 0.6rem !important; }
        [data-testid="stHorizontalBlock"] {
            flex-direction: column !important;
            gap: 0.6rem !important;
        }
        [data-testid="stHorizontalBlock"] > [data-testid="stColumn"],
        [data-testid="stHorizontalBlock"] > [data-testid="column"] {
            width: 100% !important;
            flex: 1 1 auto !important;
            min-width: 0 !important;
        }
        .login-brand-bar {
            padding: 10px 12px !important;
            margin: 0 0 10px !important;
        }
        .login-brand-logo { height: 36px !important; }
        .login-page-heading { margin: 0 0 6px !important; }
        .login-page-title {
            font-size: clamp(13px, 4.1vw, 22px) !important;
            white-space: nowrap !important;
            line-height: 1.35 !important;
            padding: 0 !important;
            letter-spacing: -0.045em !important;
        }
        .login-page-title br { display: none !important; }
        .login-page-title span { white-space: nowrap !important; }
        .login-page-title span::before { content: " "; }
        .login-page-subtitle {
            font-size: 0.75rem !important;
            margin-top: 5px !important;
        }
        div[data-testid="stForm"] { padding: 12px !important; }
        div[data-testid="stForm"] input {
            min-height: 40px !important;
            font-size: 16px !important;
        }
        div[data-testid="stFormSubmitButton"] button {
            min-height: 44px !important;
            margin-top: 2px !important;
        }
        .login-photo-panel {
            min-height: 0 !important;
            height: clamp(120px, 23vh, 180px) !important;
            height: clamp(120px, 23svh, 180px) !important;
            margin-top: 0 !important;
            border-radius: 12px !important;
        }
        .login-slide-caption {
            left: 12px !important;
            bottom: 10px !important;
            font-size: 0.82rem !important;
        }
    }
    </style>
    """, unsafe_allow_html=True)

    logo_html = (
        f'<img src="data:image/png;base64,{img_base64}" alt="한국환경공단 로고">'
        if img_base64 else '<div style="font-size:4rem;">🌱</div>'
    )
    splash_logo_html = (
        f'<img class="keco-splash-logo" src="data:image/png;base64,{img_base64}" alt="한국환경공단 로고">'
        if img_base64 else '<div style="font-size:3.5rem;">🌱</div>'
    )
    # 같은 접속 세션에서 최초 1회만 약 2초간 표시
    if not st.session_state.get("splash_shown", False):
        splash_background = (
            f"url('data:image/webp;base64,{splash_bg_base64}')"
            if splash_bg_base64 else "linear-gradient(160deg, #082C31, #06171D)"
        )
        st.markdown(
            f"""
            <div class="keco-splash" style="--splash-bg:{splash_background};animation-duration:2s !important;">
                <div class="keco-splash-art-label"><div class="splash-system-name">스마트 건설현장 안전관리 시스템</div></div>
                <div class="keco-splash-progress"></div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        st.session_state["splash_shown"] = True

    # 로그인 우측 현장사진: 파일명이 .png 또는 .png.png인 경우 모두 대응
    image_dir = Path(__file__).resolve().parent / "images"
    slide_specs = [
        (["bto.png", "bto.png.png"], "BTO 환경시설사업"),
        (["incineration.png", "incineration.png.png"], "소각시설 설치사업"),
        (["sewage.png", "sewage.png.png"], "공공하수처리시설"),
        (["livestock.png", "livestock.png.png"], "가축분뇨처리시설"),
    ]
    slide_items = []
    for file_candidates, caption in slide_specs:
        image_path = next(
            (image_dir / name for name in file_candidates if (image_dir / name).is_file()),
            None,
        )
        if image_path:
            encoded = base64.b64encode(image_path.read_bytes()).decode("utf-8")
            slide_items.append(
                f'<div class="login-slide">'
                f'<img src="data:image/png;base64,{encoded}" alt="{caption}">'
                f'<div class="login-slide-caption">{caption}</div>'
                f'</div>'
            )

    login_col, photo_col = st.columns([0.92, 1.08], gap="large")

    with login_col:
        st.markdown(
            f"""
            <div class="login-brand-bar">
                {logo_html.replace('<img ', '<img class="login-brand-logo" ')}
                <div class="login-brand-text">
                    <div class="login-brand-name">한국환경공단</div>
                    <div class="login-branch-name">수도권서부환경본부 환경시설관리처</div>
                </div>
            </div>
            <div class="login-page-heading login-heading-v24">
                <h1 class="login-page-title">스마트 건설현장 <span>안전관리 시스템</span></h1>
                <p class="login-page-subtitle">인증된 사내 감독관 전용 서비스입니다.</p>
            </div>
            """,
            unsafe_allow_html=True,
        )

        allowed_users = st.secrets.get("passwords", {})

        with st.form("supervisor_login_form", clear_on_submit=False):
            user_id = st.text_input(
                "감독관 ID(사번)",
                placeholder="사번을 입력하세요",
                key="username_input",
            )
            user_pw = st.text_input(
                "비밀번호",
                type="password",
                placeholder="비밀번호를 입력하세요",
                key="password_input",
            )
            submitted = st.form_submit_button("로그인", width="stretch")

        if submitted:
            user_id_clean = str(user_id).strip()
            user_pw_clean = str(user_pw).strip()
            allowed_users_str = {str(k): str(v) for k, v in allowed_users.items()}

            if not user_id_clean or not user_pw_clean:
                st.warning("사번과 비밀번호를 모두 입력해 주세요.")
            elif (
                user_id_clean in allowed_users_str
                and allowed_users_str[user_id_clean] == user_pw_clean
            ):
                st.session_state["password_correct"] = True
                st.session_state["logged_user"] = user_id_clean
                st.rerun()
            else:
                st.error("아이디 또는 비밀번호가 올바르지 않습니다.")

    with photo_col:
        if slide_items:
            st.markdown(
                f'<div class="login-photo-panel">{"".join(slide_items)}</div>',
                unsafe_allow_html=True,
            )
        else:
            st.markdown(
                """
                <div class="login-photo-panel" style="display:flex;align-items:center;justify-content:center;">
                    <div style="text-align:center;color:#52645C;padding:24px;">
                        <div style="font-size:3rem;margin-bottom:12px;">🌿</div>
                        환경시설 현장사진
                    </div>
                </div>
                """,
                unsafe_allow_html=True,
            )

    return False


# 여기부터는 함수 밖이므로 앞에 공백을 넣지 않습니다.
if not check_password():
    st.stop()
    
logged_user_id = st.session_state.get('logged_user')

