# --- 1. 사진 저장 & 이메일 연동 설정 ---

def save_image_to_internal_network(uploaded_file, folder_path, prefix):
    try:
        storage = nhn_storage_backend()
        if storage is not None:
            key = storage.save_bytes(inspection_file_bytes(uploaded_file), category="images")
            return f"nhn://{storage.bucket}/{storage.prefix}/{key}"
        if not os.path.exists(folder_path):
            os.makedirs(folder_path, exist_ok=True)
            
        timestamp_str = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_filename = f"{prefix}_{timestamp_str}_{uploaded_file.name}"
        full_path = os.path.join(folder_path, safe_filename)
        
        uploaded_file.seek(0)
        with open(full_path, "wb") as f:
            f.write(uploaded_file.getbuffer())
            
        return full_path
    except Exception as e:
        st.error(f"사진 저장 실패: {e}")
        return None


def _perf_private_cache():
    """Only this signed-in browser session can reuse its photos and AI results."""
    owner = str(st.session_state.get('logged_user', ''))
    cache = st.session_state.get('_perf_private_cache')
    if not isinstance(cache, dict) or cache.get('owner') != owner:
        cache = {'owner': owner, 'entries': {}}
        st.session_state['_perf_private_cache'] = cache
    return cache['entries']


def _perf_cache_get(namespace, key):
    entries = _perf_private_cache()
    entry = entries.pop((namespace, key), None)
    if entry is None or entry['expires'] <= time.monotonic():
        return None
    entries[(namespace, key)] = entry
    return entry['value']


def _perf_cache_put(namespace, key, value, ttl=3600):
    def size(item):
        if isinstance(item, bytes): return len(item)
        if isinstance(item, str): return len(item.encode('utf-8'))
        if isinstance(item, (list, tuple)): return sum(size(v) for v in item)
        return 32
    entries = _perf_private_cache()
    entries.pop((namespace, key), None)
    cost = size(value)
    if cost > 32*1024*1024: return
    entries[(namespace, key)] = {'value': value, 'bytes': cost, 'expires': time.monotonic()+ttl}
    while len(entries) > 64 or sum(v['bytes'] for v in entries.values()) > 32*1024*1024:
        entries.pop(next(iter(entries)))


def _perf_photo(raw, max_edge=1800, quality=92):
    """Prepare a derivative once; archived photos always use the original bytes."""
    from PIL import ImageOps
    key = (hashlib.sha256(raw).hexdigest(), int(max_edge), int(quality))
    cached = _perf_cache_get('photo', key)
    if cached is not None: return cached
    with Image.open(io.BytesIO(raw)) as original:
        original.draft('RGB', (max_edge, max_edge))
        photo = ImageOps.exif_transpose(original).convert('RGB')
        photo.thumbnail((max_edge, max_edge))
        output = io.BytesIO()
        photo.save(output, format='JPEG', quality=quality)
        prepared = (output.getvalue(), photo.width, photo.height)
    _perf_cache_put('photo', key, prepared)
    return prepared


def _perf_actor_allowed(actor):
    return bool(actor and st.session_state.get('password_correct') and
                str(st.session_state.get('logged_user', '')) == str(actor))


def _perf_ai_http_options(timeout_ms=60000):
    options = {'timeout': timeout_ms}
    if 'retry_options' in getattr(genai_types.HttpOptions, 'model_fields', {}):
        options['retry_options'] = {'attempts': 1}
    return options


def inspection_file_bytes(file):
    """사진 읽기 위치를 보존하여 화면·저장·이메일에서 함께 사용."""
    if hasattr(file, "getvalue"):
        return file.getvalue()
    position = file.tell()
    try:
        file.seek(0)
        return file.read()
    finally:
        file.seek(position)


def inspection_report_key(dept, site, inspector, items):
    payload = [str(dept), str(site), str(inspector)]
    for idx, item in items.items():
        payload.append([idx, item.get("desc_before", ""), item.get("desc_after", ""),
                        item.get("ai_analysis", ""),
                        [[hashlib.sha256(inspection_file_bytes(f)).hexdigest()
                          for f in item.get(key, [])]
                         for key in ("before_files", "after_files")]])
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False).encode()).hexdigest()


def generate_inspection_hwpx(dept, site, inspector, items, report_title="현장 안전점검 및 조치 결과 보고서"):
    """A4 보고서: 가운데 제목, 기본정보, 조치 전후 비교표, AI 분석."""
    from PIL import ImageOps
    if not items:
        raise ValueError("사진 또는 설명을 입력한 점검 항목이 없습니다.")
    doc = HwpxDocument.new()
    ns = {"hp": "http://www.hancom.co.kr/hwpml/2011/paragraph"}
    page = doc.sections[0].element.find(".//hp:pagePr", ns)
    if page is not None:
        page.set("width", "59528")
        page.set("height", "84189")
        margin = page.find("hp:margin", ns)
        if margin is not None:
            for side in ("left", "right", "top", "bottom"):
                margin.set(side, "5102")

    # 실제 문단 속성으로 정렬 (공백으로 위치를 맞추지 않음).
    styles = {}
    for align in ("LEFT", "CENTER", "RIGHT"):
        temp = doc.add_paragraph("")
        doc.set_paragraph_format(paragraph_index=len(doc.paragraphs) - 1,
                                 alignment=align, line_spacing_percent=135,
                                 spacing_after_pt=3)
        styles[align] = temp.element.get("paraPrIDRef")
        temp.remove()

    def paragraph(text, *, size=10, bold=False, align="LEFT", new_page=False):
        for line_number, line in enumerate(str(text).splitlines() or [""]):
            p = doc.add_paragraph("", para_pr_id_ref=styles[align],
                                  pageBreak="1" if new_page and line_number == 0 else "0")
            p.add_run(line, font="맑은 고딕", size=size, bold=bold)

    def cell_text(cell, text, *, align="LEFT", bold=False, size=10):
        cell.set_text("")
        for index, line in enumerate(str(text).splitlines() or [""]):
            p = cell.paragraphs[0] if index == 0 else cell.add_paragraph("")
            p.element.set("paraPrIDRef", styles[align])
            p.add_run(line, font="맑은 고딕", size=size, bold=bold)

    created = datetime.datetime.now(ZoneInfo("Asia/Seoul")).strftime("%Y-%m-%d %H:%M")
    paragraph(report_title, size=20, bold=True, align="CENTER")
    paragraph("")
    paragraph(f"◎ 담당부서: {dept}", size=11)
    # 테두리 없는 1행 표로 현장명과 생성시간을 같은 줄에 배치.
    info = doc.add_table(rows=1, cols=2, width=49324, height=1700)
    info.element.set("borderFillIDRef", "2")
    for col, width in enumerate((30000, 19324)):
        cell = info.cell(0, col)
        cell.set_size(width=width, height=1700)
        cell.element.set("borderFillIDRef", "2")
    cell_text(info.cell(0, 0), f"◎ 점검현장: {site}", size=10)
    cell_text(info.cell(0, 1), f"보고서 생성: {created}", size=9, align="RIGHT")
    paragraph("")

    for order, (idx, item) in enumerate(items.items()):
        paragraph(f"점검 항목 {idx}", size=13, bold=True, new_page=order > 0)
        before, after = item.get("before_files", []), item.get("after_files", [])
        for number in range(max(len(before), len(after), 1)):
            if number:
                paragraph(f"점검 항목 {idx} · 사진 {number + 1}", size=12, bold=True, new_page=True)
            heights = (2200, 21000, 4500)
            table = doc.add_table(rows=3, cols=2, width=49324, height=sum(heights))
            table.element.set("repeatHeader", "1")
            for row in range(3):
                for col in range(2):
                    table.cell(row, col).set_size(width=24662, height=heights[row])
            for col, (label, files, description) in enumerate((
                ("조치 전 내용", before, item.get("desc_before") or "내용 없음"),
                ("조치 후 내용", after, item.get("desc_after") or "내용 없음"),
            )):
                cell_text(table.cell(0, col), label, align="CENTER", bold=True, size=11)
                photo_cell = table.cell(1, col)
                cell_text(table.cell(2, col), description)
                if number >= len(files):
                    cell_text(photo_cell, "등록된 사진 없음", align="CENTER")
                    continue
                try:
                    picture, photo_width, photo_height = _perf_photo(inspection_file_bytes(files[number]))
                    scale = min(80 / photo_width, 67 / photo_height)
                    obj = doc.add_picture(picture, "jpg", width_mm=photo_width * scale,
                                          height_mm=photo_height * scale, align="CENTER")
                    # add_picture가 만든 그림 문단을 해당 표 셀 안으로 이동.
                    picture_p = obj.element
                    while picture_p.tag != "{%s}p" % ns["hp"]:
                        picture_p = picture_p.getparent()
                    picture_p.set("paraPrIDRef", styles["CENTER"])
                    sublist = photo_cell.element.find("hp:subList", ns)
                    for child in list(sublist):
                        sublist.remove(child)
                    sublist.append(picture_p)
                except Exception as exc:
                    raise ValueError(f"항목 {idx} {label} 사진 {number + 1} 삽입 실패: {exc}") from exc
            paragraph("")
        analysis = str(item.get("ai_analysis") or "").strip()
        if analysis and analysis != "분석 미실행":
            paragraph("조치 전 사진 AI 분석 결과", size=11, bold=True)
            paragraph(analysis)
            paragraph("※ AI 분석은 참고자료이며 최종 판단은 현장 확인 결과에 따릅니다.", size=9)
    output = io.BytesIO()
    doc.save_to_stream(output)
    return output.getvalue()


def inspection_store():
    """NHN 연결 시 기록을 Object Storage에 보관하고 재시작 때 복원."""
    db = nhn_record_connection("reports.sqlite3")
    db.execute("CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, owner TEXT, dept TEXT, site TEXT, created TEXT, payload TEXT)")
    db.execute("CREATE TABLE IF NOT EXISTS deliveries (id TEXT PRIMARY KEY, status TEXT, detail TEXT)")
    return db


def archive_inspection(dept, site, owner, items, hwpx=None, pdf=None):
    now = datetime.datetime.now(ZoneInfo("Asia/Seoul"))
    day = now.strftime("%Y-%m-%d")
    key = day + ":" + inspection_report_key(dept, site, owner, items)
    payload = {}
    for idx, item in items.items():
        payload[str(idx)] = {k: str(item.get(k, "")) for k in ("desc_before", "desc_after", "ai_analysis")}
        for field in ("before_files", "after_files"):
            payload[str(idx)][field] = [inspection_photo_pack(f) for f in item.get(field, [])]
    db = inspection_store()
    try:
        with db:
            report_history_require_active(db, "inspection", key)
            db.execute("INSERT OR IGNORE INTO reports VALUES (?, ?, ?, ?, ?, ?)",
                       (key, str(owner), dept, site, now.isoformat(timespec="seconds"), json.dumps(payload, ensure_ascii=False)))
            if hwpx is not None or pdf is not None:
                db.execute("""CREATE TABLE IF NOT EXISTS report_files (
                    id TEXT PRIMARY KEY, hwpx BLOB, pdf BLOB)""")
                db.execute("INSERT OR REPLACE INTO report_files VALUES (?,?,?)", (key, hwpx, pdf))
    finally:
        db.close()
    return key


def generate_inspection_pdf(dept, site, inspector, items, report_title="현장 안전점검 및 조치 결과 보고서"):
    """HWPX와 동일한 입력으로 만드는 A4 출력용 PDF. 긴 설명은 표 밖에서 이어짐."""
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image as PDFImage, PageBreak
    from PIL import ImageOps
    from xml.sax.saxutils import escape
    # Nanum Gothic (SIL Open Font License 1.1): 글꼴 원본과 라이선스를 코드에 포함.
