# 대시보드 집계는 NHN 저장소의 점검 기록을 기준으로 합니다.
from html import escape as dashboard_escape


def dashboard_frame(records):
    columns = ['기록ID','날짜','점검 부서','점검 현장','항목수','AI분석','지적 분류','작성자','사진경로','자료 상태']
    df = pd.DataFrame(records, columns=columns).fillna('')
    df['기록번호'] = range(1,len(df)+1)
    def parse_day(value):
        try:
            ts = pd.to_datetime(str(value), errors='coerce')
            if pd.isna(ts):
                return pd.NaT
            if ts.tzinfo is not None:
                ts = ts.tz_convert('Asia/Seoul').tz_localize(None)
            return ts
        except (ValueError, TypeError):
            return pd.NaT
    df['일시'] = pd.to_datetime(df['날짜'].map(parse_day))
    df['점검항목수'] = pd.to_numeric(df['항목수'].map(inspection_history_item_count), errors='coerce')
    for field in ['점검 부서','점검 현장','작성자']:
        df[field] = df[field].astype(str).str.strip().replace('', '미기재')
    df['분석여부'] = df['AI분석'].map(lambda value: bool(str(value).strip()) and str(value).strip() not in ('분석 미실행','조치 전 AI 분석 미실행','없음','nan'))
    return df


def dashboard_risk_counts(df):
    groups = {
        '추락·개구부': ('추락', '난간', '개구부', '비계', '발판'),
        '끼임·협착': ('끼임', '협착', '롤러', '회전체'),
        '화재·폭발': ('화재', '폭발', '용접', '인화성'),
        '전기·감전': ('전기', '감전', '누전', '충전부'),
        '굴착·붕괴': ('굴착', '붕괴', '흙막이', '토사'),
        '밀폐공간·질식': ('밀폐공간', '질식', '산소', '유해가스'),
    }
    texts = df.loc[df['분석여부'], 'AI분석'].astype(str)
    return pd.DataFrame([{'위험 키워드': name, '언급 기록': sum(any(k in t for k in keys) for t in texts)}
                         for name, keys in groups.items()])


def dashboard_chart_style(fig, height=330):
    fig.update_layout(template='plotly_white', height=height,
                      font=dict(family='Malgun Gothic, sans-serif', size=12, color='#334155'),
                      paper_bgcolor='rgba(0,0,0,0)', plot_bgcolor='rgba(0,0,0,0)',
                      margin=dict(l=8, r=24, t=24, b=8),
                      xaxis=dict(gridcolor='#edf2f7', zeroline=False),
                      yaxis=dict(gridcolor='#edf2f7', zeroline=False),
                      hoverlabel=dict(bgcolor='white'), showlegend=False)
    return fig


