@st.fragment
def render_ai_guide_panel(logged_user_id):
    if not _perf_actor_allowed(logged_user_id): return
    st.subheader("안전 업무, AI에게 물어보세요")
    st.markdown("화면 아래 질문 칸에 궁금한 내용을 적고 보내세요.")
    st.caption("예: 굴착 작업 전에 무엇을 확인해야 하나요? · 안전난간 점검 항목을 알려주세요.")

    with st.expander('법령을 찾아 답변에 참고하기', expanded=True):
        st.caption('건설·산업안전 관련 등록 법령을 함께 검토합니다. 질문 범위에 따라 검토 시간이 걸릴 수 있습니다.')
        law_use, law_context, law_sources = render_law_panel()

    if "qa_messages" not in st.session_state:
        st.session_state.qa_messages = [
            {"role": "assistant", "content": "안녕하세요! 푸루·그루입니다. 환경시설 건설현장 안전 규정이나 지침에 대해 무엇이든 물어보세요!"}
        ]

    # 기존 대화 기록 출력
    for msg in st.session_state.qa_messages:
        with st.chat_message(msg["role"]):
            st.markdown(msg["content"])

    # 단 하나의 채팅 입력창
    if user_query := st.chat_input("예: 밀폐공간 작업 시 산소 및 유해가스 측정 기준이 어떻게 되나요?"):
        if law_use:
            law_key = str(st.secrets.get('public_api', {}).get('law_oc', '')).strip()
            if not law_key:
                st.warning('법령 API 연결 설정이 필요합니다. 관리자에게 문의하세요.'); st.stop()
            with st.spinner('등록 법령 전체에서 질문과 관련된 조문을 검토하고 있습니다…'):
                try:
                    docs = st.session_state.get('law_all_documents', [])
                    if len(docs) != len(LAW_CHOICES) or st.session_state.get('law_all_errors'):
                        docs, errors = law_collect_all(law_key, datetime.datetime.now().strftime('%Y%m%d%H'))
                        st.session_state.law_all_documents = docs
                        st.session_state.law_all_errors = errors
                        if errors:
                            raise ValueError('법령 조회 미완료: ' + ', '.join(errors) + '. 전체 법령 최신 내용 다시 조회를 눌러주세요.')
                    law_models = _ai_model_candidates('law')
                    def select_law_articles(prompt):
                        result = _ai_request(api_key,prompt,law_models,config={
                            'response_mime_type':'application/json',
                            'response_schema':{'type':'OBJECT','properties':{
                                'ids':{'type':'ARRAY','items':{'type':'INTEGER'}}},'required':['ids']}})
                        return _ai_response_text(result)
                    selection_sig = hashlib.sha256(json.dumps(
                        [hashlib.sha256(str(api_key).encode()).hexdigest(), law_models, 'ids-json-v2', docs, user_query],
                        ensure_ascii=False, sort_keys=True).encode()).hexdigest()
                    selected = _perf_cache_get('law_selection', selection_sig)
                    if selected is None:
                        selected = law_question_context(docs, user_query, select_law_articles)
                        _perf_cache_put('law_selection', selection_sig, selected, ttl=900)
                    law_context, law_sources = selected
                except ValueError as exc:
                    st.warning('전체 법령 검토를 완료하지 못했습니다. '+str(exc)); st.stop()
                except Exception as exc:
                    st.error('전체 법령 검토를 완료하지 못했습니다. '+str(_ai_connection_error(exc))); st.stop()
